def count_positive(nums):
    # 检查列表是否为空，如果为空返回0
    if not nums:
        return 0
    count = 0
    # 遍历列表中的每个元素
    for x in nums:
        # 如果元素大于0，计数器加1
        if x > 0:
            count += 1
    return count
